<style>
:root{--green:#00f5a0;--panel:#092126;--line:rgba(123,238,207,.31);--muted:#abc3be;--gold:#f1ce70;--red:#ff6f7b;--blue:#71d9ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:#f3fffb;font-family:Roboto,sans-serif;background:linear-gradient(rgba(1,13,17,.82),rgba(1,13,17,.95)),url('{{ asset("Imagenes/Pantalla_Inicio.jpg") }}') center/cover fixed}.page{width:min(1280px,calc(100% - 24px));margin:auto;padding:22px 0 50px}.top,.room-meta,.controls,.final-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.back,.btn,button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 14px;border-radius:10px;font-weight:800;font-family:Roboto;text-decoration:none;cursor:pointer}.back,.secondary{color:#e0fcf4;border:1px solid var(--line);background:rgba(0,0,0,.22)}.primary{border:0;background:var(--green);color:#032019}.warning{border:1px solid rgba(241,206,112,.42);color:var(--gold);background:rgba(241,206,112,.07)}.danger{border:1px solid rgba(255,111,123,.45);color:#ffabb2;background:rgba(255,111,123,.07)}.room-meta{margin:19px 0;padding:15px 19px;border:1px solid var(--line);border-radius:15px;background:rgba(6,27,32,.95)}.code{font:700 19px monospace;letter-spacing:3px;color:var(--gold)}.status{padding:6px 11px;border-radius:99px;background:rgba(0,245,160,.1);color:#8df2ca;font-weight:800;font-size:13px}.message{padding:12px 15px;border-radius:11px;margin-bottom:14px}.success{background:#174936;color:#aff7d8}.error{background:#61282e;color:#ffd1d5}.layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:18px}.classroom,.ranking{border:1px solid var(--line);border-radius:19px;background:rgba(6,27,32,.96);overflow:hidden}.classroom{min-height:650px;padding:21px;background:linear-gradient(rgba(6,27,32,.93),rgba(6,27,32,.98)),repeating-linear-gradient(90deg,transparent 0 90px,rgba(255,255,255,.018) 91px 92px)}.board{position:relative;min-height:260px;padding:24px;border:8px solid #7d583a;border-radius:9px;background:linear-gradient(145deg,#173d37,#0e2d29);box-shadow:inset 0 0 30px rgba(0,0,0,.45),0 10px 25px rgba(0,0,0,.25)}.board:after{content:"";position:absolute;left:-13px;right:-13px;bottom:-18px;height:11px;border-radius:5px;background:#9a7048}.board-head{display:flex;justify-content:space-between;color:#bdd9d1;font-size:13px;gap:10px}.board h1{font-family:'Press Start 2P';font-size:clamp(18px,3vw,29px);line-height:1.55;color:#fff;text-align:center;margin:24px auto;max-width:800px}.waiting{text-align:center;color:var(--muted);padding:28px 10px}.waiting i{color:var(--green);font-size:40px;margin-bottom:12px}.timer{display:grid;place-items:center;width:58px;height:58px;border-radius:50%;margin:auto;border:3px solid var(--gold);color:var(--gold);font-size:21px;font-weight:900}.answer-form{max-width:760px;margin:18px auto 0}.options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.option{display:flex;align-items:center;gap:10px;padding:13px;border:1px solid rgba(255,255,255,.22);border-radius:10px;background:rgba(0,0,0,.18);cursor:pointer}.option:has(input:checked){border-color:var(--green);background:rgba(0,245,160,.1)}.option input{accent-color:var(--green)}.direct{width:100%;padding:13px;border:1px solid var(--line);border-radius:10px;background:#06191d;color:white;font:inherit}.answer-form button{width:100%;margin-top:12px}.feedback{text-align:center;padding:18px;border-radius:13px;margin-top:18px}.feedback.correct{background:rgba(24,142,91,.42);border:1px solid #75efb7}.feedback.incorrect{background:rgba(167,52,63,.4);border:1px solid #ff8b95}.feedback strong{display:block;font-size:22px;margin-bottom:7px}.desks-title{margin:35px 0 12px;color:var(--gold);text-align:center}.desks{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.desk{text-align:center;padding:11px 6px 8px;border-radius:8px 8px 14px 14px;background:linear-gradient(#9a7048 0 9px,#523922 10px 100%);box-shadow:0 8px 0 #2f231a;color:#fff;min-width:0}.desk i{display:block;color:var(--green);margin-bottom:5px}.desk.offline i{color:#7d918d}.desk span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.ranking{padding:20px;height:max-content;position:sticky;top:16px}.ranking h2{margin:0 0 7px}.ranking p{margin:0 0 17px;color:var(--muted)}.rank-list{display:grid;gap:8px}.rank{display:grid;grid-template-columns:34px 1fr auto;gap:8px;align-items:center;padding:10px;border-radius:10px;background:#06191d}.rank:first-child{border:1px solid rgba(241,206,112,.55);background:rgba(241,206,112,.08)}.place{color:var(--gold);font-weight:900}.points{color:#9df0ce;font-weight:900}.controls{justify-content:flex-start;margin-top:16px;padding:15px;border:1px solid var(--line);border-radius:14px;background:rgba(6,27,32,.95)}.controls form{margin:0}.winner{text-align:center;padding:18px}.trophy{font-size:54px;color:var(--gold);filter:drop-shadow(0 0 16px rgba(241,206,112,.35))}.winner h2{font-family:'Press Start 2P';color:var(--gold);line-height:1.5}.final-actions{justify-content:center;margin-top:16px}.connection{color:var(--muted);font-size:12px;margin-left:auto}@media(max-width:980px){.layout{grid-template-columns:1fr}.ranking{position:static}.desks{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:650px){.classroom{padding:12px}.board{padding:16px}.options{grid-template-columns:1fr}.desks{grid-template-columns:repeat(3,minmax(0,1fr))}.room-meta{align-items:flex-start}.layout{gap:12px}}
</style></head><body><main class="page">
<div class="top"><a class="back" href="{{ route('alumno.tests.amigos.index') }}"><i class="fas fa-arrow-left"></i> Test con amigos</a><span class="connection" id="connection"><i class="fas fa-circle"></i> Conectando…</span></div>
<section class="room-meta"><div><small>MESA DE ESTUDIO</small><div class="code">{{ $sesion->codigo_sala }}</div></div><div><strong id="participantCount">{{ $estado['participantes'] }}</strong> / 30 participantes</div><span class="status" id="status">{{ ucfirst($estado['fase']) }}</span></section>
@if(session('success'))<div class="message success">{{ session('success') }}</div>@endif @if(session('error'))<div class="message error">{{ session('error') }}</div>@endif
<div class="layout"><section class="classroom"><div class="board" id="board"><div class="board-head"><span id="roundLabel">Sala de espera</span><span id="goalLabel">Meta: {{ $sesion->puntaje_objetivo }} puntos</span></div><div id="boardContent"></div></div><h3 class="desks-title"><i class="fas fa-users"></i> Nuestro salón</h3><div class="desks" id="desks"></div></section>
<aside class="ranking"><h2><i class="fas fa-ranking-star" style="color:var(--gold)"></i> Clasificación</h2><p>Se actualiza al terminar cada pregunta.</p><div class="rank-list" id="ranking"></div></aside></div>
<section class="controls" id="hostControls" style="{{ $estado['sesion']['es_anfitrion']?'':'display:none' }}">
