<form id="finishForm" method="POST" action="{{ route('alumno.tests.amigos.finish',$sesion) }}" onsubmit="return confirm('¿Terminar esta partida?')">@csrf<button class="danger"><i class="fas fa-stop"></i> Terminar</button></form>
<div class="final-actions" id="finalActions"><form method="POST" action="{{ route('alumno.tests.amigos.repeat',$sesion) }}">@csrf<button class="primary"><i class="fas fa-rotate-right"></i> Jugar otra vez</button></form><a class="btn secondary" href="{{ route('alumno.tests.amigos.configure',$sesion) }}"><i class="fas fa-sliders"></i> Cambiar reglas</a></div>
</section>
</main><script>
const initialState=@json($estado);const stateUrl=@json(route('tests.live.state',$sesion));const answerUrl=@json(route('tests.live.answer',$sesion));const reconnectUrl=@json(route('tests.live.reconnect',$sesion));const csrf=document.querySelector('meta[name="csrf-token"]').content;const tokenKey='codeplay-live-token-{{ $sesion->id }}';@if($token)localStorage.setItem(tokenKey,@json($token));@endif
let current=initialState,lastKey='',polling=false;const el=id=>document.getElementById(id);const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function answerLabel(value,question){const key=String(value);if(question?.opciones&&Object.prototype.hasOwnProperty.call(question.opciones,key))return question.opciones[key];if(['1','true'].includes(key.toLowerCase()))return 'Verdadero';if(['0','false'].includes(key.toLowerCase()))return 'Falso';return key}
function render(data){current=data;const phase=data.fase;el('status').textContent=phase==='activa'?'Pregunta activa':phase==='resultado'?'Resultado':phase==='espera'?'Sala de espera':phase==='configuracion'?'Configurando':phase==='pausada'?'Pausada':phase==='finalizada'?'Finalizada':'Cerrada';el('participantCount').textContent=data.participantes;el('roundLabel').textContent=data.sesion.ronda?`Ronda ${data.sesion.ronda} · Pregunta ${data.sesion.pregunta_numero}`:'Sala de espera';el('goalLabel').textContent=`Meta: ${data.sesion.puntaje_objetivo??'—'} puntos`;
el('desks').innerHTML=data.clasificacion.map(p=>`<div class="desk ${p.conectado?'':'offline'}"><i class="fas fa-user"></i><span>${escapeHtml(p.nombre)}</span></div>`).join('')||'<div class="waiting">Aún no hay alumnos.</div>';el('ranking').innerHTML=data.clasificacion.map(p=>`<div class="rank"><span class="place">${p.posicion}</span><span>${escapeHtml(p.nombre)}</span><span class="points">${p.puntos}</span></div>`).join('')||'<p>La clasificación aparecerá aquí.</p>';
const host=data.sesion.es_anfitrion;el('hostControls').style.display=host?'flex':'none';el('startForm').style.display=host&&phase==='espera'?'block':'none';el('pauseForm').style.display=host&&phase==='activa'?'block':'none';el('resumeForm').style.display=host&&phase==='pausada'?'block':'none';el('finishForm').style.display=host&&['espera','activa','pausada','configuracion'].includes(phase)?'block':'none';el('finalActions').style.display=host&&['finalizada','cerrada'].includes(phase)?'flex':'none';
const key=`${data.pregunta?.id??0}-${phase}-${data.mi_resultado?.respondio??false}`;if(key!==lastKey){lastKey=key;renderBoard(data)}if(data.pregunta&&phase==='activa'){const timer=el('timer');if(timer)timer.textContent=data.pregunta.segundos_restantes}}
function renderBoard(data){const phase=data.fase,board=el('boardContent');if(['espera','configuracion'].includes(phase)){board.innerHTML=`<div class="waiting"><i class="fas fa-chalkboard-user"></i><h2>${phase==='configuracion'?'El anfitrión está cambiando las reglas':'Esperando al anfitrión'}</h2><p>${data.participantes} participante(s) están en la mesa.</p></div>`;return}if(['finalizada','cerrada'].includes(phase)){const w=data.ganador;board.innerHTML=`<div class="winner"><i class="fas fa-trophy trophy"></i><h2>${w?escapeHtml(w.nombre):'Partida terminada'}</h2><p>${w?`Ganó con <strong>${w.puntos} puntos</strong>.`:'Consulta la clasificación final.'}</p></div>`;return}if(!data.pregunta){board.innerHTML='<div class="waiting"><p>Preparando la siguiente pregunta…</p></div>';return}const q=data.pregunta;if(phase==='resultado'){const mine=data.mi_resultado;const correct=mine?.correcta;const expected=(q.respuestas_correctas||[]).map(v=>escapeHtml(answerLabel(v,q))).join(', ');board.innerHTML=`<div class="timer"><i class="fas fa-check"></i></div><div class="feedback ${correct?'correct':'incorrect'}"><strong>${correct?'¡Respuesta correcta!':'Respuesta incorrecta'}</strong><span>Sumaste ${mine?.puntos_sumados??0} puntos · Llevas ${mine?.puntos_totales??0}</span><p>Respuesta: ${expected||'—'}</p>${q.explicacion?`<small>${escapeHtml(q.explicacion)}</small>`:''}</div>`;return}const paused=phase==='pausada';let form='';if(data.mi_resultado?.respondio){form='<div class="waiting"><i class="fas fa-hourglass-half"></i><h2>Respuesta registrada</h2><p>Esperando a tus compañeros…</p></div>'}else if(!data.mi_resultado){form='<div class="waiting"><p>Observando como anfitrión.</p></div>'}else{form=buildAnswer(q,paused)}board.innerHTML=`<div class="timer" id="timer">${paused?'<i class="fas fa-pause"></i>':q.segundos_restantes}</div><h1>${escapeHtml(q.enunciado)}</h1>${form}`;const answerForm=el('answerForm');if(answerForm)answerForm.addEventListener('submit',submitAnswer)}
function buildAnswer(q,paused){let fields='';if(q.tipo==='respuesta_directa'){fields='<input class="direct" name="respuesta" maxlength="1000" autocomplete="off" required placeholder="Escribe tu respuesta">'}else{let options=q.opciones||{};if(q.tipo==='verdadero_falso')options={'true':'Verdadero','false':'Falso'};const multiple=q.tipo==='seleccion_multiple';fields=`<div class="options">${Object.entries(options).map(([key,label])=>`<label class="option"><input type="${multiple?'checkbox':'radio'}" name="respuesta${multiple?'[]':''}" value="${escapeHtml(key)}" ${multiple?'':'required'}> <span>${escapeHtml(label)}</span></label>`).join('')}</div>`}return `<form class="answer-form" id="answerForm">${fields}<button class="primary" ${paused?'disabled':''}><i class="fas fa-paper-plane"></i> Responder</button></form>`}
async function submitAnswer(event){event.preventDefault();const form=new FormData(event.currentTarget);const values=form.getAll('respuesta[]');const answer=values.length?values:form.get('respuesta');if(answer===null||answer===''||(Array.isArray(answer)&&!answer.length))return;event.currentTarget.querySelector('button').disabled=true;try{const response=await fetch(answerUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({respuesta:answer})});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'No se pudo registrar la respuesta.');render(data)}catch(error){alert(error.message);event.currentTarget.querySelector('button').disabled=false}}
async function reconnect(){const token=localStorage.getItem(tokenKey);if(!token)return false;try{const response=await fetch(reconnectUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({reconexion_token:token})});const data=await response.json();if(!response.ok||!data.success)return false;localStorage.setItem(tokenKey,data.reconexion_token);return true}catch{return false}}
async function poll(){if(polling)return;polling=true;try{let response=await fetch(stateUrl,{headers:{'Accept':'application/json'},cache:'no-store'});if(response.status===422&&await reconnect())response=await fetch(stateUrl,{headers:{'Accept':'application/json'},cache:'no-store'});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'Sin conexión');render(data);el('connection').innerHTML='<i class="fas fa-circle" style="color:var(--green)"></i> Sincronizado'}catch(error){el('connection').innerHTML='<i class="fas fa-circle" style="color:var(--red)"></i> Reconectando…'}finally{polling=false}}
render(initialState);setInterval(poll,1000);
</script></body></html>
